// Methods of Comparison — Comparison, route: jsx
// Source: methods-of-comparison-compared
//
// Self-contained: every local import is inlined below. Requires only d3, geojson, react, topojson-client, topojson-specification, us-atlas, world-atlas.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { feature, mesh } from 'topojson-client';
import countries110m from 'world-atlas/countries-110m.json';
import statesUs from 'us-atlas/states-10m.json';
import type { GeometryCollection, Topology } from 'topojson-specification';
import type { Feature, FeatureCollection, Geometry, MultiLineString } from 'geojson';
import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from geo ----
// The atlases ship untyped JSON. One cast per topology at this boundary keeps every
// consumer strict, and converting here means each chart does not re-derive the same
// geometry at module load.

type Named = { name: string };
type NamedFeature = Feature<Geometry, Named>;

const world = countries110m as unknown as Topology<{
  countries: GeometryCollection<Named>;
  land: GeometryCollection;
}>;

const us = statesUs as unknown as Topology<{
  states: GeometryCollection<Named>;
  nation: GeometryCollection;
}>;

const worldCountries = feature(
  world,
  world.objects.countries
) as FeatureCollection<Geometry, Named>;

const worldLand = feature(world, world.objects.land) as FeatureCollection<Geometry>;

/** Shared borders only, so neighbouring outlines are stroked once instead of twice. */
const worldBorders = mesh(
  world,
  world.objects.countries,
  (a, b) => a !== b
) as MultiLineString;

const usNation = feature(us, us.objects.nation) as FeatureCollection<Geometry>;

const usStateBorders = mesh(
  us,
  us.objects.states,
  (a, b) => a !== b
) as MultiLineString;

/**
 * The 50 states plus DC. geoAlbersUsa cannot project FIPS ids of 60 and above
 * (territories) and returns null for them, which becomes a NaN centroid downstream.
 * Use this rather than the raw collection for anything Albers-projected.
 */
const usStates: NamedFeature[] = (
  feature(us, us.objects.states) as FeatureCollection<Geometry, Named>
).features.filter((d) => Number(d.id) < 60);

const usStatesCollection: FeatureCollection<Geometry, Named> = {
  type: 'FeatureCollection',
  features: usStates
};

/**
 * FNV-1a over an id, run through the murmur3 finalizer. Two-character FIPS ids barely
 * differ, and without the finalizer they map to a near-constant. Returns [0, 1).
 * Charts use it to synthesize per-region values deterministically instead of fetching.
 */
function hashUnit(id: string, salt = 0): number {
  let h = 2166136261 ^ salt;
  for (let i = 0; i < id.length; i++) {
    h = Math.imul(h ^ id.charCodeAt(i), 16777619);
  }
  h ^= h >>> 16;
  h = Math.imul(h, 2246822507);
  h ^= h >>> 13;
  return (h >>> 0) / 4294967296;
}

// ---- inlined from methodsOfComparison ----
type ComparisonRow_methodsOfComparison = { id: string; name: string; a: number; b: number };

/**
 * Seeded stand-in for the IHME alcohol-mortality series (deaths per 100,000, 1980 vs 2014).
 * Low starting rates are deliberately given faster growth: that correlation is what makes
 * relative change blow up on small denominators, which is the point the figure compares.
 * Order matches `usStates`, so a chart can zip geometry and rows by index.
 */
const comparisonRows: ComparisonRow_methodsOfComparison[] = usStates.map((feature) => {
  const id = String(feature.id);
  const a = 2 + 22 * hashUnit(id, 1) ** 2;
  const logRatio = -0.9 + 1.9 * hashUnit(id, 2) ** 1.4 - 0.04 * (a - 12);
  return { id, name: feature.properties.name, a, b: a * Math.exp(logRatio) };
});

/**
 * One row per region, carrying the pair of values being compared. Rows must be in the same
 * order as `usStates`, because the panels zip geometry to its datum by index.
 */
export type Data = { id: string; name: string; a: number; b: number }[];

type ComparisonRow = Data[number];

const MARGIN = { top: 8, right: 8, bottom: 8, left: 8 };
const GUTTER = 10;
const LABEL_H = 16;
const LEGEND_H = 30;
const CAPTION_H = 18;
const RAMP_STOPS = 28;

const fmtRate = d3.format('.0f');
const fmtOne = d3.format('.1f');
const fmtDiff = d3.format('+.1f');
const fmtPct = d3.format('+.0%');
const fmtRatio = (x: number) => `${d3.format('.2~r')(x)}×`;

/** Blues below zero, Reds above: the notebook's two-sided interpolator over [-1, 1]. */
const diverging = (s: number) => {
  const t = Math.max(-1, Math.min(1, s));
  return t < 0 ? d3.interpolateBlues(-t) : d3.interpolateReds(t);
};

type Panel = {
  key: string;
  label: string;
  short: string;
  paint: (row: ComparisonRow) => string;
  ramp: (t: number) => string;
  lo: string;
  hi: string;
};

const difference = (r: ComparisonRow) => r.b - r.a;
const relative = (r: ComparisonRow) => (r.b - r.a) / r.a;
const ratio = (r: ComparisonRow) => r.b / r.a;

function buildPanels(rows: Data): Panel[] {
  const peak = d3.max(rows, (r) => Math.max(r.a, r.b)) ?? 1;
  const seq = d3.scaleSqrt().domain([0, peak]).range([0, 1]);
  const seqColor = (v: number) => d3.interpolateBuPu(seq(v));

  const dMax = Math.max(-(d3.min(rows, difference) ?? 0), d3.max(rows, difference) ?? 0);
  const dNorm = d3.scaleSqrt().domain([-dMax, 0, dMax]).range([-1, 0, 1]);

  const rMin = d3.min(rows, relative) ?? 0;
  const rMax = d3.max(rows, relative) ?? 0;
  const rSym = Math.max(-rMin, rMax);
  const fitNorm = d3.scaleLinear().domain([rMin, 0, rMax]).range([-1, 0, 1]);
  const symNorm = d3.scaleLinear().domain([-rSym, 0, rSym]).range([-1, 0, 1]);

  const lMax = Math.max(d3.max(rows, ratio) ?? 1, 1 / (d3.min(rows, ratio) ?? 1));
  const lNorm = d3.scaleLog().domain([1 / lMax, 1, lMax]).range([-1, 0, 1]);

  const twoSided = (t: number) => diverging(2 * t - 1);

  return [
    {
      key: 'a', label: '1980 rate', short: '1980',
      paint: (r) => seqColor(r.a), ramp: (t) => seqColor(t * peak),
      lo: '0', hi: fmtRate(peak)
    },
    {
      key: 'b', label: '2014 rate', short: '2014',
      paint: (r) => seqColor(r.b), ramp: (t) => seqColor(t * peak),
      lo: '0', hi: fmtRate(peak)
    },
    {
      key: 'difference', label: 'Difference, b − a', short: 'Difference',
      paint: (r) => diverging(dNorm(difference(r))), ramp: twoSided,
      lo: fmtDiff(-dMax), hi: fmtDiff(dMax)
    },
    {
      key: 'relative', label: 'Relative change, fitted', short: 'Relative',
      paint: (r) => diverging(fitNorm(relative(r))),
      // Linear in value through an asymmetric domain, so the legend's white sits off-centre.
      ramp: (t) => diverging(fitNorm(rMin + t * (rMax - rMin))),
      lo: fmtPct(rMin), hi: fmtPct(rMax)
    },
    {
      key: 'symmetric', label: 'Relative change, symmetric', short: 'Symmetric',
      paint: (r) => diverging(symNorm(relative(r))), ramp: twoSided,
      lo: fmtPct(-rSym), hi: fmtPct(rSym)
    },
    {
      key: 'logratio', label: 'Log ratio, b ÷ a', short: 'Log ratio',
      paint: (r) => diverging(lNorm(ratio(r))), ramp: twoSided,
      lo: fmtRatio(1 / lMax), hi: fmtRatio(lMax)
    }
  ];
}

export default function MethodsOfComparison({
  data = comparisonRows,
  width
}: {
  data?: Data;
  width: number;
}) {
  const columns = width < 560 ? 2 : 3;
  const innerWidth = Math.max(1, width - MARGIN.left - MARGIN.right);
  const cellWidth = innerWidth / columns;
  const mapWidth = Math.max(1, cellWidth - GUTTER);
  const mapHeight = mapWidth * 0.58;
  const cellHeight = LABEL_H + mapHeight + LEGEND_H;
  const rowCount = Math.ceil(6 / columns);
  const height = Math.round(MARGIN.top + rowCount * cellHeight + CAPTION_H + MARGIN.bottom);

  const panels = useMemo(() => buildPanels(data), [data]);

  const shapes = useMemo(() => {
    const projection = d3.geoAlbersUsa().fitSize([mapWidth, mapHeight], usStatesCollection);
    const path = d3.geoPath(projection);
    // The rows are in usStates order, so index zips geometry to its datum.
    return {
      states: usStates.map((f, i) => ({ row: data[i], d: path(f) ?? '' })),
      borders: path(usStateBorders) ?? ''
    };
  }, [data, mapWidth, mapHeight]);

  if (width === 0) return null;

  const showLabels = cellWidth >= 84;
  const showLegendText = cellWidth >= 110;
  const rampStep = mapWidth / RAMP_STOPS;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label={
        'Six US state choropleths of the same pair of values, encoded as 1980 rate, 2014 rate, ' +
        'difference, fitted relative change, symmetric relative change and log ratio, so the ' +
        'encodings can be compared. Synthetic data from a seeded generator, not the IHME ' +
        'alcohol use disorder mortality series.'
      }
    >
      {panels.map((panel, i) => {
        const x = MARGIN.left + (i % columns) * cellWidth;
        const y = MARGIN.top + Math.floor(i / columns) * cellHeight;
        return (
          <g key={panel.key} transform={`translate(${x},${y})`}>
            {showLabels && (
              <text y={11} fill="var(--text)" fontSize={10} fontWeight={600}>
                {cellWidth >= 150 ? panel.label : panel.short}
              </text>
            )}
            <g transform={`translate(0,${LABEL_H})`}>
              {shapes.states.map((s) => (
                <path key={s.row.id} d={s.d} fill={panel.paint(s.row)}>
                  <title>{`${s.row.name}\n1980 ${fmtOne(s.row.a)}\n2014 ${fmtOne(s.row.b)}`}</title>
                </path>
              ))}
              <path d={shapes.borders} fill="none" stroke="var(--panel)" strokeWidth={0.5} />
            </g>
            <g transform={`translate(0,${LABEL_H + mapHeight + 8})`}>
              {d3.range(RAMP_STOPS).map((step) => (
                <rect
                  key={step}
                  x={step * rampStep}
                  y={0}
                  width={rampStep + 0.5}
                  height={7}
                  fill={panel.ramp(step / (RAMP_STOPS - 1))}
                />
              ))}
              {showLegendText && (
                <>
                  <text y={18} fill="var(--muted)" fontSize={9}>
                    {panel.lo}
                  </text>
                  <text x={mapWidth} y={18} textAnchor="end" fill="var(--muted)" fontSize={9}>
                    {panel.hi}
                  </text>
                </>
              )}
            </g>
          </g>
        );
      })}

      <text
        x={MARGIN.left}
        y={height - MARGIN.bottom - 4}
        fill="var(--muted)"
        fontSize={9}
      >
        {width >= 420
          ? 'Synthetic data from a seeded generator, not the IHME alcohol mortality series.'
          : 'Synthetic data, not a real series.'}
      </text>
    </svg>
  );
}
